insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('e23ab7b6-8f7f-4dea-b8f0-2c7768c3b0fe', 'N5', 'なにも Vません', 'Không làm gì cả', 'なにも + phủ định = không...gì cả', 'なにも + V(thể phủ định)', 'Phủ định toàn bộ hành động, nghĩa là không làm bất kỳ việc gì', NULL, NULL, NULL, '{"どこ(へ)もいきません"}', NULL, 36, 'なにも Vません', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('cab5f045-b9c2-4682-8284-87e794e23f2b', 'N5', 'どこで N を Vます', 'Làm gì ở đâu', 'で đánh dấu nơi diễn ra hành động', 'どこ + で + N + を + Vます', 'Hỏi/trả lời địa điểm diễn ra 1 hành động cụ thể', NULL, NULL, 'で (nơi diễn ra hành động) khác に (nơi tồn tại/đích đến) — không dùng lẫn.', '{}', NULL, 36, 'どこで N を Vます', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('cce07fee-8266-4245-a1e6-e7d06243dce7', 'N5', 'いっしょに Vませんか', 'Cùng làm gì với mình chứ? (lời mời/rủ rê)', 'ませんか (phủ định + か) dùng để mời một cách lịch sự', 'いっしょに + V(thể ます phủ định) + か', 'Rủ rê/mời ai đó cùng làm 1 việc một cách lịch sự', 'lịch sự, thân thiện', 'Trả lời đồng ý: ええ、いいですね。 Từ chối khéo: すみません、ちょっと…', NULL, '{"Vましょう"}', NULL, 36, 'いっしょに Vませんか', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('3ae34551-3ee1-4435-8125-5d4ba7f43638', 'N5', 'V ましょう', 'Làm ... thôi! (đề nghị/rủ rê hành động chung)', 'ましょう = thôi mình cùng làm nhé', 'V(thể ます) → V + ましょう', 'Đề nghị/rủ rê cùng thực hiện 1 hành động, sắc thái chủ động hơn ませんか', NULL, NULL, NULL, '{"いっしょに Vませんか"}', NULL, 36, 'V ましょう', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('81376f13-09a6-4639-a56e-f2e6308ce094', 'N5', 'なにで Vますか（N で + V ます）', 'Làm việc gì bằng phương tiện/công cụ gì', 'で ở đây đánh dấu công cụ/phương tiện thực hiện hành động', 'なにで + Vますか → trả lời: N(công cụ) + で + Vます', 'Hỏi/trả lời công cụ hoặc phương tiện dùng để làm việc gì', NULL, NULL, NULL, '{}', NULL, 36, 'なにで Vますか（N で + V ます）', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('8d93317a-9bd3-4b30-b3c6-3f4e9c002338', 'N5', '（Từ/Câu）は～語で何ですか', '"Từ/câu" trong tiếng ~ là gì?', '～語 = tiếng ~ (英語=tiếng Anh, 日本語=tiếng Nhật)', '「Từ/Câu」+ は + ～語で + 何ですか', 'Hỏi cách nói 1 từ/câu bằng ngôn ngữ khác', NULL, NULL, NULL, '{}', NULL, 36, '（Từ/Câu）は～語で何ですか', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('16c1bb6a-98b1-43e7-a0b3-807a149a29cb', 'N5', 'だれに 何を Vますか（N1 に N2 を Vます）', 'Làm gì cho ai (trao/gửi/dạy cho ai cái gì)', 'に đánh dấu người nhận', 'だれに + 何を + Vますか → trả lời: N1(người) + に + N2(vật) + を + Vます', 'Hỏi/trả lời hành động trao/gửi/dạy... hướng tới 1 người cụ thể', NULL, 'Động từ hay dùng: あげます, 貸します, 書きます, 電話をかけます, 教えます, 送ります, ...', NULL, '{}', NULL, 36, 'だれに 何を Vますか（N1 に N2 を Vます）', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('858e0712-db92-42be-88c9-9fa28bd4d541', 'N5', 'だれに（から）何を Vますか（nhận）', 'Ai đó làm gì cho mình / nhận cái gì từ ai', 'もらいます/借ります/習います = nhận/mượn/học từ ai đó (dùng に hoặc から)', 'N1(người cho) + に／から + N2(vật) + を + もらいます／借ります／習います', 'Diễn tả việc nhận, mượn, hoặc học được cái gì từ người khác', NULL, 'Động từ hay dùng: もらいます, 借ります, 習います.', NULL, '{"だれに 何を Vますか（N1 に N2 を Vます）"}', NULL, 37, 'だれに（から）何を Vますか（nhận）', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('d872d7b8-f56c-4a25-9fa5-9702e020e8cf', 'N5', 'だれが くれましたか', 'Ai đã tặng/cho cái gì (cho chính mình)', 'くれます chỉ dùng khi người khác cho MÌNH, không dùng cho việc mình cho người khác', 'N1(người, thường là chủ ngữ)が(は) + N2(vật) + を + くれます', 'Hỏi/trả lời ai đã tặng/cho mình 1 vật gì đó', NULL, NULL, 'くれます khác あげます: くれます = người khác cho TÔI, あげます = TÔI cho người khác.', '{}', NULL, 37, 'だれが くれましたか', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('5ed97dfd-145f-4652-864d-a3a92a41866f', 'N5', 'もう + Vましたか', 'Bạn đã làm ~ rồi phải không?', 'もう = đã (chưa)？ trả lời: はい、もう~／いいえ、まだです', 'もう + V(thể ました) + か', 'Hỏi xem 1 việc đã hoàn thành hay chưa', NULL, 'Trả lời: はい、もうVました (Vâng, đã làm rồi) ／ いいえ、まだです。これからVます。 (Chưa, bây giờ mới chuẩn bị làm)', NULL, '{}', NULL, 37, 'もう + Vましたか', 'pdf', 'ok')
insert into jp_grammar (id, level, grammar_pattern, meaning_vi, memory_hint_vi, connection, usage, register, notes, common_mistake, similar_patterns, difference_note, source_page, source_text, source_type, review_status) values ('41c8e6c8-bd80-4942-a5e3-ab8052b147f4', 'N5', 'そして；が', 'Và, hơn nữa (そして) ； Nhưng, tuy nhiên (が)', 'そして nối 2 câu cùng chiều; が nối 2 câu ngược/tương phản', 'S1。そして、S2。 ／ S1が、S2。', 'Nối 2 câu — そして bổ sung thêm ý cùng chiều, が nêu ý tương phản', NULL, NULL, 'が ở đây là liên từ "nhưng", khác với trợ từ が đánh dấu chủ ngữ.', '{}', NULL, 37, 'そして；が', 'pdf', 'ok')
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('bf9b29d7-50c3-4e30-ab8d-c359d35ccff7', '41c8e6c8-bd80-4942-a5e3-ab8052b147f4', 1, 'そして: Và, hơn nữa — nối 2 câu cùng chiều ý nghĩa', 'S1。そして、S2。', 'Bổ sung thêm thông tin cùng chiều với câu trước', NULL, 37, 'pdf');
insert into jp_grammar_usages (id, grammar_id, usage_no, meaning, connection, usage, notes, source_page, source_type) values ('9dbcd755-1e2d-4f5b-ba10-1b5b4de876bb', '41c8e6c8-bd80-4942-a5e3-ab8052b147f4', 2, 'が: Nhưng, tuy nhiên — nối 2 câu ý nghĩa tương phản', 'S1が、S2。', 'Nêu ý tương phản/trái ngược với câu trước', NULL, 37, 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e23ab7b6-8f7f-4dea-b8f0-2c7768c3b0fe', NULL, 1, 'standard', '明日、何をしますか。', 'Ngày mai bạn sẽ làm gì?', '明日、＿＿＿をしますか。', '何', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e23ab7b6-8f7f-4dea-b8f0-2c7768c3b0fe', NULL, 2, 'standard', '何もしません。', 'Tôi không làm gì cả.', '＿＿＿もしません。', '何', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('e23ab7b6-8f7f-4dea-b8f0-2c7768c3b0fe', NULL, 3, 'daily', '今日は何も食べません。', 'Hôm nay tôi không ăn gì cả.', '今日は＿＿＿も食べません。', '何', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('cab5f045-b9c2-4682-8284-87e794e23f2b', NULL, 1, 'standard', 'ズン森で日本語を勉強します。', 'Tôi học tiếng Nhật ở Trung tâm Dũng Mori.', 'ズン森＿＿＿日本語を勉強します。', 'で', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('cab5f045-b9c2-4682-8284-87e794e23f2b', NULL, 2, 'standard', 'どこで写真を撮りましたか。', 'Bạn đã chụp ảnh ở đâu vậy?', '＿＿＿で写真を撮りましたか。', 'どこ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('cab5f045-b9c2-4682-8284-87e794e23f2b', NULL, 3, 'standard', '日本で撮りました。', 'Tôi đã chụp ở Nhật Bản.', '日本＿＿＿撮りました。', 'で', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('cce07fee-8266-4245-a1e6-e7d06243dce7', NULL, 1, 'standard', 'いっしょに昼ご飯を食べませんか。', 'Cùng nhau ăn cơm trưa chứ?', 'いっしょに昼ご飯を食べ＿＿＿か。', 'ません', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('cce07fee-8266-4245-a1e6-e7d06243dce7', NULL, 2, 'standard', 'いっしょにスーパーへ行きませんか。', 'Cùng nhau đi siêu thị chứ?', 'いっしょにスーパーへ行き＿＿＿か。', 'ません', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('cce07fee-8266-4245-a1e6-e7d06243dce7', NULL, 3, 'standard', 'ええ、いいですね。', 'Vâng, được đấy nhỉ.', '＿＿＿、いいですね。', 'ええ', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('3ae34551-3ee1-4435-8125-5d4ba7f43638', NULL, 1, 'standard', 'いっしょにビールを飲みませんか。', 'Cùng nhau uống bia chứ?', 'いっしょにビールを飲み＿＿＿か。', 'ません', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('3ae34551-3ee1-4435-8125-5d4ba7f43638', NULL, 2, 'standard', 'ええ、飲みましょう。', 'Vâng, uống bia thôi nào!', 'ええ、飲み＿＿＿。', 'ましょう', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('3ae34551-3ee1-4435-8125-5d4ba7f43638', NULL, 3, 'daily', '食べましょう。', 'Ăn thôi nào!', '食べ＿＿＿。', 'ましょう', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('81376f13-09a6-4639-a56e-f2e6308ce094', NULL, 1, 'standard', 'なにで紙を切りますか。', 'Bạn cắt giấy bằng gì?', '＿＿＿紙を切りますか。', 'なにで', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('81376f13-09a6-4639-a56e-f2e6308ce094', NULL, 2, 'standard', 'はさみで紙を切ります。', 'Tôi cắt giấy bằng kéo.', '＿＿＿紙を切ります。', 'はさみで', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('81376f13-09a6-4639-a56e-f2e6308ce094', NULL, 3, 'standard', 'パソコンで勉強します。', 'Tôi học bằng laptop.', '＿＿＿勉強します。', 'パソコンで', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8d93317a-9bd3-4b30-b3c6-3f4e9c002338', NULL, 1, 'standard', '「ありがとう」は英語で何ですか。', 'Từ "cảm ơn" trong tiếng Anh là gì?', '「ありがとう」は＿＿＿で何ですか。', '英語', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8d93317a-9bd3-4b30-b3c6-3f4e9c002338', NULL, 2, 'standard', '「Tết」は日本語で何ですか。', 'Từ "Tết" trong tiếng Nhật là gì?', '「Tết」は＿＿＿で何ですか。', '日本語', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('8d93317a-9bd3-4b30-b3c6-3f4e9c002338', NULL, 3, 'standard', '「お正月」です。', 'Là "お正月".', '「お正月」＿＿＿。', 'です', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('16c1bb6a-98b1-43e7-a0b3-807a149a29cb', NULL, 1, 'standard', 'だれに電話をかけますか。', 'Bạn gọi điện cho ai vậy?', '＿＿＿電話をかけますか。', 'だれに', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('16c1bb6a-98b1-43e7-a0b3-807a149a29cb', NULL, 2, 'standard', '家族に電話をかけます。', 'Tôi gọi điện cho gia đình.', '＿＿＿電話をかけます。', '家族に', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('16c1bb6a-98b1-43e7-a0b3-807a149a29cb', NULL, 3, 'standard', 'アインさんに教えます。', 'Bạn Ánh dạy cho tôi.', '＿＿＿教えます。', 'アインさんに', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('858e0712-db92-42be-88c9-9fa28bd4d541', NULL, 1, 'standard', '私は母にシャツをもらいます。', 'Tôi nhận được áo sơ mi từ mẹ.', '私は母＿＿＿シャツをもらいます。', 'に', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('858e0712-db92-42be-88c9-9fa28bd4d541', NULL, 2, 'daily', '友達に本を借ります。', 'Tôi mượn sách từ bạn.', '友達＿＿＿本を借ります。', 'に', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('858e0712-db92-42be-88c9-9fa28bd4d541', NULL, 3, 'daily', '先生から日本語を習います。', 'Tôi học tiếng Nhật từ thầy giáo.', '先生＿＿＿日本語を習います。', 'から', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('d872d7b8-f56c-4a25-9fa5-9702e020e8cf', NULL, 1, 'standard', 'だれがこの鉛筆をくれましたか。', 'Ai đã tặng cây bút chì này cho bạn vậy?', '＿＿＿この鉛筆をくれましたか。', 'だれが', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('d872d7b8-f56c-4a25-9fa5-9702e020e8cf', NULL, 2, 'standard', 'アインさんがくれました。', 'Chị Ánh đã tặng cho tôi.', 'アインさん＿＿＿くれました。', 'が', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('d872d7b8-f56c-4a25-9fa5-9702e020e8cf', NULL, 3, 'daily', '先生がノートをくれました。', 'Thầy giáo đã cho tôi quyển vở.', '先生＿＿＿ノートをくれました。', 'が', 'generated');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('5ed97dfd-145f-4652-864d-a3a92a41866f', NULL, 1, 'standard', 'もう、朝ごはんを食べましたか。', 'Bạn đã ăn sáng rồi phải không?', '＿＿＿、朝ごはんを食べましたか。', 'もう', 'pdf');
insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('5ed97dfd-145f-4652-864d-a3a92a41866f', NULL, 2, 'standard', 'はい、もう食べました。', 'Vâng, tôi đã ăn sáng rồi.', 'はい、＿＿＿食べました。', 'もう', 'pdf');
