insert into jp_grammar_examples (grammar_id, usage_id, example_no, example_type, example_jp, example_vi, cloze_jp, answer, source_type) values ('41c8e6c8-bd80-4942-a5e3-ab8052b147f4', 'bf9b29d7-50c3-4e30-ab8d-c359d35ccff7', 1, 'standard', 'ベトナム料理は美味しいです。そして安いです。', 'Món ăn của Việt Nam ngon. Hơn nữa giá còn rẻ.', 'ベトナム料理は美味しいです。＿＿＿安いです。', 'そして', 'pdf');
