insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('41c8e6c8-bd80-4942-a5e3-ab8052b147f4', 'bf9b29d7-50c3-4e30-ab8d-c359d35ccff7', 'choose_meaning', 'Mẫu ngữ pháp nào có nghĩa: "そして: Và, hơn nữa — nối 2 câu cùng chiều ý nghĩa"?', 'そして；が', 'いっしょに Vませんか', 'だれが くれましたか', 'なにも Vません', 'そして；が', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('41c8e6c8-bd80-4942-a5e3-ab8052b147f4', 'bf9b29d7-50c3-4e30-ab8d-c359d35ccff7', 'choose_connection', 'Cách nối đúng của mẫu "そして；が" (そして: Và, hơn nữa — nối 2 câu cùng chiều ý nghĩa) là gì?', 'S1。そして、S2。', 'どこ + で + N + を + Vます', 'もう + V(thể ました) + か', 'なにで + Vますか → trả lời: N(công cụ) + で + Vます', 'S1。そして、S2。', 'generated');
