insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('41c8e6c8-bd80-4942-a5e3-ab8052b147f4', '9dbcd755-1e2d-4f5b-ba10-1b5b4de876bb', 'choose_meaning', 'Mẫu ngữ pháp nào có nghĩa: "が: Nhưng, tuy nhiên — nối 2 câu ý nghĩa tương phản"?', 'だれに 何を Vますか（N1 に N2 を Vます）', '（Từ/Câu）は～語で何ですか', 'そして；が', 'V ましょう', 'そして；が', 'generated');
insert into jp_grammar_questions (grammar_id, usage_id, question_type, question_text, choice_1, choice_2, choice_3, choice_4, correct_answer, source_type) values ('41c8e6c8-bd80-4942-a5e3-ab8052b147f4', '9dbcd755-1e2d-4f5b-ba10-1b5b4de876bb', 'choose_connection', 'Cách nối đúng của mẫu "そして；が" (が: Nhưng, tuy nhiên — nối 2 câu ý nghĩa tương phản) là gì?', 'S1。そして、S2。 ／ S1が、S2。', '「Từ/Câu」+ は + ～語で + 何ですか', 'S1が、S2。', 'なにも + V(thể phủ định)', 'S1が、S2。', 'generated');
